import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 10 章 写代码：脚本、修改与调试（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第10章 写代码：脚本、修改与调试（易懂版）.md","filePath":"easy/第10章 写代码：脚本、修改与调试（易懂版）.md"}'),s={name:"easy/第10章 写代码：脚本、修改与调试（易懂版）.md"};function n(l,t,d,i,h,u){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-10-章-写代码-脚本、修改与调试-易懂版" tabindex="-1">第 10 章 写代码：脚本、修改与调试（易懂版） <a class="header-anchor" href="#第-10-章-写代码-脚本、修改与调试-易懂版" aria-label="Permalink to &quot;第 10 章 写代码：脚本、修改与调试（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 10 章 写代码：脚本、修改与调试（完整版）](../../bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 10 章 写代码：脚本、修改与调试.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>不懂编程也能让我写代码——但要知道怎么&quot;提需求&quot;和&quot;验结果&quot;。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>你不需要会修车，也能把车送进修理厂。但你要会说清楚：<strong>车什么症状、想修成什么样</strong>。</p><p>写代码也一样：<strong>你描述问题，我动手写；修好修坏，我们一起试。</strong></p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>说症状不说病因</strong>：告诉我要达到什么效果（&quot;把文件夹里所有图片压缩到 1MB 以内&quot;），而不是猜技术方案（&quot;用 xxx 库&quot;）。</li><li><strong>改完要能验</strong>：每次改完，告诉我<strong>怎么验证</strong>（跑哪个命令、看哪个结果），我才能自检。</li><li><strong>小步快跑</strong>：一次改一小块、跑一次、看结果——<strong>别攒一堆再试，出错难找</strong>。</li></ol><h2 id="三个高频场景" tabindex="-1">三个高频场景 <a class="header-anchor" href="#三个高频场景" aria-label="Permalink to &quot;三个高频场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>你该说什么</th><th>你会得到</th></tr></thead><tbody><tr><td><strong>写新脚本</strong></td><td>输入什么、输出什么、放哪</td><td>一个能跑的脚本 + 使用方法</td></tr><tr><td><strong>改旧代码</strong></td><td>哪段有问题、想要什么效果</td><td>改好的代码 + 改了什么说明</td></tr><tr><td><strong>查 bug</strong></td><td>什么时候出错、报错长啥样</td><td>定位原因 + 修复 + 验证</td></tr></tbody></table><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;写个脚本：读取 <code>订单.xlsx</code>，把金额列加起来，输出总金额，存到 <code>结果.txt</code>。&quot;</p><p><strong>你会看到</strong>：我写脚本 → 跑一遍 → 给你看运行结果 → 确认数字对不对。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 让我&quot;随便写个程序&quot;——<strong>输入输出必须讲清楚</strong>；</li><li>❌ 看都不看就点运行——<strong>让我先自测，你再验收</strong>；</li><li>❌ 把代码当黑盒——<strong>至少知道它碰了哪些文件</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>写代码 = 说清输入输出 + 小步快跑 + 跑给你看。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>想一个你常做的重复操作（改名？压缩？汇总？）——<strong>它可能 3 分钟就变成一个脚本。</strong> 试试对我说：&quot;写个脚本，把……&quot;</p><p>👉 [下一章：文件与目录，整理、搜索、批量处理（易懂版）](第11章 文件与目录：整理、搜索、批量处理（易懂版）.md)</p>',20)])])}const g=o(s,[["render",n]]);export{_ as __pageData,g as default};
